(()=>{
 const role=new URLSearchParams(location.search).get('testRole')||'client';let user=role==='guest'?null:{id:role,email:'TEST-'+role+'@example.invalid'};
 const row=(id,kind,owner_id,parent_id,statut,payload)=>({id,kind,owner_id,parent_id,statut,payload,revision:1,created_at:'2026-10-08T10:00:00Z'});
 const records=[row('driver','chauffeurs','driver',null,'Disponible',{nom:'TEST Chauffeur',telephone:'+999000000001'}),row('vehicle','vehicules','driver','driver','Actif',{nom:'TEST Taxi',categorie:'Taxi',immatriculation:'TEST'}),row('professional','professionnels','merchant',null,'Actif',{nom:'TEST Boutique',type:'Les deux',telephone:'+999000000002'}),row('shop','boutiques','merchant','professional','Actif',{nom:'TEST Boutique',adresse:'TEST Koki'}),row('product','produits','merchant','shop','Disponible',{nom:'TEST Riz',prix:500,stock:2,description:'TEST produit',categorie:'Alimentation'}),row('service','services','merchant','professional','Disponible',{nom:'TEST Plomberie',description:'TEST prestation',categorie:'Plomberie',prix:null})];
 const calls=[];const operations=new Map();let fail=null;
 window.businessMock={calls,records,noDrivers:false,noRate:false,fail:(type='network')=>{fail=type;}};
 const query=table=>{const filters=[];const q={select(){return q;},eq(k,v){filters.push([k,v]);return q;},order(){return q;},limit(){return q;},then(resolve){let data=table==='koki_transport_rates'?[{category:'Taxi',base_fcfa:500,per_km_fcfa:250,active:true}]:records;data=data.filter(r=>filters.every(([k,v])=>r[k]===v));return Promise.resolve({data:structuredClone(data)}).then(resolve);}};return q;};
 const db={supabaseUrl:'https://test.supabase.co',from:query,auth:{getUser:async()=>({data:{user}}),signInWithPassword:async()=>{user={id:'client',email:'TEST-client@example.invalid'};return {};},resetPasswordForEmail:async(email,options)=>{calls.push({command:'reset_password',email,options});return {};},updateUser:async()=>({}),signUp:async()=>({}),signOut:async()=>{user=null;return {};}},storage:{from:()=>({upload:async(path,file)=>{calls.push({command:'upload',path,size:file.size,type:file.type});return {};},createSignedUrl:async()=>({error:{message:'TEST no image'}})})},rpc:async(name,{command,input})=>{calls.push({name,command,input:structuredClone(input)});await new Promise(r=>setTimeout(r,30));if(fail){const f=fail;fail=null;if(f==='network')throw Error('TEST réseau interrompu');return {error:{code:'42501',message:'TEST denied'}};}if(command==='catalog')return {data:records.filter(x=>['professionnels','boutiques','produits','services'].includes(x.kind)).map(x=>({id:x.id,kind:x.kind,parent_id:x.parent_id,...x.payload}))};if(command==='history')return {data:structuredClone(records.filter(x=>x.kind===input.kind))};if(command==='quote'&&window.businessMock.noRate)return {error:{code:'P0001',message:'Tarif validé indisponible'}};if(command==='quote')return {data:{quote_id:'quote',expires_at:new Date(Date.now()+300000).toISOString(),distance_km:2,fare_fcfa:1000}};if(command==='nearby_drivers'&&window.businessMock.noDrivers)return {data:[]};if(command==='nearby_drivers')return {data:[{driver_id:'driver',vehicle_id:'vehicle',name:'TEST Chauffeur',category:'Taxi',proximity:'À proximité (moins de 10 km)'}]};if(command==='get'){const r=records.find(r=>r.id===input.id);return {data:{...structuredClone(r),items:[{product_name:'TEST Riz',unit_price:500,quantity:1}]}};}const key=user.id+input.request_id;if(operations.has(key))return {data:structuredClone(operations.get(key))};let result;
 if(command==='reserve_ride'){result=row('ride','courses',null,'vehicle','En attente',{nom:'TEST Course',tarif:1000});result.client_id='client';result.driver_id='driver';records.push(result);}
 else if(command==='create_order'){result=row('order','commandes',null,'shop','Commande reçue',{nom:'TEST Commande',total:input.items.reduce((n,x)=>n+x.quantity*500,0),mode:input.mode});result.client_id='client';result.provider_id='professional';records.push(result);}
 else if(command==='request_service'){result=row('request','demandes_services',null,'service','Demande envoyée',{nom:'TEST Demande',besoin:input.need,lieu:input.address,image_path:input.image_path});result.client_id='client';result.provider_id='professional';records.push(result);}
 else if(command==='transition'){result=records.find(r=>r.id===input.id);result.statut=input.next;result.revision++;}
 else if(command==='admin_review'){result=records.find(r=>r.id===input.id);result.statut=input.decision==='approve'?'Actif':'Suspendu';result.revision++;}
 else if(['save_product','save_service','save_vehicle','save_shop'].includes(command)){result=records.find(r=>r.id===input.id)||row('TEST-new',({save_product:'produits',save_service:'services',save_vehicle:'vehicules',save_shop:'boutiques'})[command],user.id,input.parent_id,'Disponible',{});result.payload={nom:input.name,description:input.description,categorie:input.category,prix:input.price,stock:input.stock,image_path:input.image_path};result.revision++;if(!records.includes(result))records.push(result);}
 else if(command==='set_rate')result={category:input.category,...input};
 else result={id:'TEST-saved',revision:1,payload:{nom:'TEST saved'}};
 operations.set(key,structuredClone(result));return {data:structuredClone(result)};}};
 window.supabase={createClient:()=>db};window.testBusinessDB=db;
})();
